    /// The binary parameter points the existing suite pins, as
    /// `(m, primitive polynomial, n, k, t)`.
    const LEGACY_BINARY_POINTS: &[(usize, u64, usize, usize, usize)] = &[
        (3, 0b1011, 7, 4, 1),
        (4, 0b10011, 15, 11, 1),
        (4, 0b10011, 15, 7, 2),
        (5, 0b100101, 31, 26, 1),
        (6, 0b1000011, 63, 57, 1),
        (7, 0b10000011, 127, 64, 10),
    ];

    fn binary_extension(m: usize, modulus: u64) -> BinaryPrimeExt {
        BinaryPrimeExt::new(Gf2mField::new(m, modulus)).expect("a primitive modulus")
    }

    fn binary_narrow_sense(m: usize, modulus: u64, designed_distance: u64) -> BinaryBchCode {
        BinaryBchCode::construct(BchSpec::PrimitiveNarrowSense {
            extension: binary_extension(m, modulus),
            designed_distance: DesignedDistance::try_from(designed_distance)
                .expect("a positive designed distance"),
        })
        .expect("a valid primitive narrow-sense spec")
    }

    fn root_seeds(values: impl IntoIterator<Item = u64>) -> Box<[RootExponent]> {
        values
            .into_iter()
            .map(RootExponent::from)
            .collect::<Vec<_>>()
            .into_boxed_slice()
    }

    fn lift_generator<X: FieldExtension>(
        extension: &X,
        generator: &FieldPoly<X::Base>,
    ) -> FieldPoly<X::Ext> {
        FieldPoly::new(
            generator
                .iter()
                .map(|coefficient| extension.embed(coefficient))
                .collect(),
        )
    }

    fn assert_same_code_observables<X, S, M>(actual: &BchCode<X, S, M>, expected: &BchCode<X, S, M>)
    where
        X: FieldExtension,
        S: SymbolSequence<X::Base>,
        M: SymbolMatrix<X::Base>,
    {
        assert_eq!(actual.generator(), expected.generator());
        assert_eq!(actual.n(), expected.n());
        assert_eq!(actual.k(), expected.k());
        assert_eq!(actual.defining_set(), expected.defining_set());
        assert_eq!(actual.distance_bound(), expected.distance_bound());
        assert_eq!(actual.correction_radius(), expected.correction_radius());
    }

    /// GF(25) = GF(5)[x] / (x^2 + x + 1).
    fn gf25() -> QuotientField<Fp<5>> {
        let modulus = FieldPoly::new(vec![Fp::<5>::new(1), Fp::new(1), Fp::new(1)]);
        QuotientField::new(Fp::<5>::zero(), modulus).expect("an irreducible modulus")
    }

    /// GF(81) presented as a degree-two extension of GF(9).
    fn gf81_over_gf9() -> QuotientField<QuotientElement<Fp<3>>> {
        let gf9_modulus = select_modulus(&Fp::<3>::zero(), 2).expect("a GF(9) modulus");
        let gf9 = QuotientField::new(Fp::<3>::zero(), gf9_modulus).expect("GF(9)");
        let gf9_zero = gf9.ext_zero();
        let gf81_modulus = select_modulus(&gf9_zero, 2).expect("a relative GF(81) modulus");
        QuotientField::new(gf9_zero, gf81_modulus).expect("GF(81) over GF(9)")
    }

